import{_ as e,o as a,c as n,ae as o}from"./chunks/framework.DQC_QtFV.js";const g=JSON.parse('{"title":"Advanced settings","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/console/advanced.md","filePath":"en/guide/console/advanced.md","lastUpdated":1793162416000}'),r={name:"en/guide/console/advanced.md"};function s(d,t,h,i,c,l){return a(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="advanced-settings" tabindex="-1">Advanced settings <a class="header-anchor" href="#advanced-settings" aria-label="Permalink to &quot;Advanced settings&quot;">​</a></h1><p>The advanced page holds the rarely changed numbers and switches, in six cards.</p><h2 id="读取范围-the-scope" tabindex="-1">读取范围: the scope <a class="header-anchor" href="#读取范围-the-scope" aria-label="Permalink to &quot;读取范围: the scope&quot;">​</a></h2><p>Which conversations the driver reads - the outer boundary of the bot&#39;s allow list, enforced by the driver. Two modes: <strong>全部会话</strong> (all) or <strong>仅选中的会话</strong> (only the selected ones, chosen in the 状态 column on <a href="./conversations.html">Conversations</a>). Switching from 全部会话 seeds the selection with what the driver reads today, so the switch never drops the whole mirror out of the scope in one step.</p><h2 id="发送节奏-the-pacing" tabindex="-1">发送节奏: the pacing <a class="header-anchor" href="#发送节奏-the-pacing" aria-label="Permalink to &quot;发送节奏: the pacing&quot;">​</a></h2><p>Every send goes through the driver&#39;s queue, which the client cannot bypass. A conversation that exceeds its character budget waits for the window to free room.</p><table tabindex="0"><thead><tr><th>Item</th><th>Default</th><th>What it is</th></tr></thead><tbody><tr><td>最小间隔</td><td>—</td><td>the minimum interval between two actions (seconds)</td></tr><tr><td>中文速度</td><td>—</td><td>Chinese characters typed per minute</td></tr><tr><td>其他字符速度</td><td>—</td><td>other characters per minute (English, digits, faces)</td></tr><tr><td>图片和贴纸</td><td>—</td><td>what one image or sticker costs in Chinese characters</td></tr><tr><td>小黄脸</td><td>—</td><td>what one QQ face costs in Chinese characters</td></tr><tr><td>统计窗口</td><td>—</td><td>how long a stretch counts as one conversation&#39;s typing; 0 means interval only</td></tr><tr><td>最长等待</td><td>—</td><td>the most one send may wait before it errors</td></tr></tbody></table><p><strong>Keep the defaults</strong>: with an automated chat client, behaviour matters as much as the method.</p><h2 id="合并消息-batching" tabindex="-1">合并消息: batching <a class="header-anchor" href="#合并消息-batching" aria-label="Permalink to &quot;合并消息: batching&quot;">​</a></h2><p>How long messages arriving back to back in one conversation are collected before a turn starts (seconds):</p><table tabindex="0"><thead><tr><th>Item</th><th>Default</th><th>What it is</th></tr></thead><tbody><tr><td>静默等待</td><td>2</td><td>after the last message, how long to wait</td></tr><tr><td>轮次进行中</td><td>5</td><td>while the previous turn is still running</td></tr><tr><td>同一人连续发</td><td>2</td><td>when the same person keeps typing</td></tr><tr><td>换人发</td><td>0.5</td><td>when someone else answers</td></tr><tr><td>被叫到的上限</td><td>1</td><td>the most a batch that @s the bot may wait</td></tr><tr><td>一批的上限</td><td>8</td><td>from this batch&#39;s first message, the most it may take</td></tr></tbody></table><h2 id="排队-the-queue" tabindex="-1">排队: the queue <a class="header-anchor" href="#排队-the-queue" aria-label="Permalink to &quot;排队: the queue&quot;">​</a></h2><p>Which waiting conversation is answered first.</p><ul><li><strong>饿等上限</strong> (the starvation guard, 120 s by default): a conversation that has waited this long goes first, whatever Jev says.</li><li><strong>需要程度</strong> (urgency): Jev may reorder by how urgently a conversation needs an answer, threshold 0-2, with the same three modes and an optional criterion.</li></ul><h2 id="空闲轮-the-free-turn" tabindex="-1">空闲轮: the free turn <a class="header-anchor" href="#空闲轮-the-free-turn" aria-label="Permalink to &quot;空闲轮: the free turn&quot;">​</a></h2><p>After this many minutes with no turn at all, the bot opens a turn of its own that belongs to no conversation, to spend on whatever it finds interesting - searching, reading, using its tools, writing notes - or on nothing. 0 is off, which is where it ships. Any turn start resets the timer, and the free turn counts as one; it does not open while the bot is paused, has no admin, or is running a turn. The ceiling is one day.</p><h2 id="工具-tools" tabindex="-1">工具: tools <a class="header-anchor" href="#工具-tools" aria-label="Permalink to &quot;工具: tools&quot;">​</a></h2><p><code>code_exec</code> moves the edge tools behind one coding tool: the model writes a script that calls them. On by default; turning it off is the documented fallback for a model that is bad at <code>code_exec</code>. The change takes effect at the next window.</p>',18)])])}const m=e(r,[["render",s]]);export{g as __pageData,m as default};
